sudo -u postgres psql <<'EOF'
CREATE ROLE app_user LOGIN PASSWORD 'Str0ng#Pass';
CREATE DATABASE shop OWNER app_user;
SHOW password_encryption;
SELECT rolname, left(rolpassword, 14) AS hash_start
  FROM pg_authid WHERE rolname = 'app_user';
EOF

SELECT line_number, auth_method, error
  FROM pg_hba_file_rules
 WHERE error IS NOT NULL;

SELECT rule_number, line_number, type, database, user_name, address, netmask, auth_method
  FROM pg_hba_file_rules
 WHERE line_number > 132;

SELECT rule_number, line_number, database, user_name, address, auth_method
  FROM pg_hba_file_rules
 WHERE type = 'host' AND rule_number <= 4;
SELECT pg_reload_conf();

SET password_encryption = 'md5';
CREATE ROLE legacy_user LOGIN PASSWORD 'Old#Pass1';
RESET password_encryption;

SELECT rolname, left(rolpassword, 14) AS hash_start
  FROM pg_authid
 WHERE rolpassword LIKE 'md5%';

ALTER ROLE legacy_user PASSWORD 'New#Pass2';
SELECT rolname, left(rolpassword, 14) AS hash_start
  FROM pg_authid
 WHERE rolname IN ('app_user', 'legacy_user')
 ORDER BY rolname;

